source=(ROOT/'assets/game.js').read_text()
probe=r'''window.__fundingMatrix=(seed,scenario)=>{__townTest.reset(scenario,seed);G.policy.educationBudget=0;G.policy.defenseBudget=0;G.policy.serviceVoucherBudget=100;const entry=seekPrivateServiceInvestment('school');__townTest.step(120);const fire=seekPrivateServiceInvestment('fire');__townTest.step(120);const hs=G.households.filter(h=>h.people.length).sort((a,b)=>migrationSpendable(a).spendable-migrationSpendable(b).spendable),picked=[hs[0],hs[hs.length>>1],hs.at(-1)],sample=()=>picked.map(h=>({id:h.id,liquidity:migrationSpendable(h).spendable,forecast:migrationServiceAt(readBuild(h.home)),publicSchool:localCivicCoverage('school',h.id),privateSchool:G.privateServiceProvision?.school?.[h.id]||0,fire:privateFireResponse(readBuild(h.home)),migration:migrationAssessment(readBuild(h.home),[{age:12,skill:.5,health:90}],2500).services})),absent=sample(),before=totalMoney(),saved=archivePayload();G.policy.educationBudget=1000;G.policy.healthBudget=1000;__townTest.step(1);const funded=sample(),fundedCash=totalMoney();if(!validateTown().ok||Math.abs(totalMoney()-before)>1)throw Error('Funding matrix books');const restored=hydrateSave(saved);if(!restored)throw Error('Funded archive restore');const f=G.firms.find(f=>f.privateService==='school'&&!f.closed),payroll={eligible:!!f,providerCash:f?.cash};if(f){const removed=f.cash;G.region+=removed;f.cash=0;payroll.removedToFiniteRegion=removed;payroll.migration=sample().map(x=>x.migration.privateSchoolOffer||null);payroll.providerCashAfter=f.cash;payroll.books=totalMoney();}
const h=G.households.find(h=>h.id===picked[0].id),home=readBuild(h.home),port=graph().portals.get(home.id),cut=(graph().neighbors.get(port)||[]).filter(id=>G.tiles[id]===1);for(const id of cut)G.tiles[id]=0;invalidateRoads(false);const disconnected={cut,forecast:migrationServiceAt(home),migration:migrationAssessment(home,[{age:12,skill:.5,health:90}],2500)};for(const id of cut)G.tiles[id]=1;invalidateRoads(false);const reconnected=migrationServiceAt(home);if(!validateTown().ok||Math.max(...goodsBalance().map(x=>Math.abs(x.error)))>.001)throw Error('Transport/books invalid');const checkpoint=archivePayload();__townTest.step(10);const future=archivePayload();if(!hydrateSave(checkpoint))throw Error('Roundtrip failed');__townTest.step(10);if(archivePayload()!==future)throw Error('Replay differs');return {seed,scenario,entry,fire,absent,funded,fundedCash,payroll,disconnected,reconnected,valid:validateTown(),cashDrift:totalMoney()-before,goods:goodsBalance()};};'''
rows=[];out=ROOT/'reports/service-access-matrix';out.mkdir(exist_ok=True)
